INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'CRE.G7.OVERVI.IMPORTANCE_OF_STUDYING_C', 'cre', 7, 'Say why learning CRE matters and how it grows good values', ARRAY['CRE.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.a', 'CRE.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.b', 'CRE.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.c']::text[], 'The child says CRE helps people know God, grow in values such as honesty, respect, love and responsibility, and live well with others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'CRE.G7.CREATI.ACCOUNTS_OF_CREATION', 'cre', 7, 'Tell the two accounts of creation and what they teach about God', ARRAY['CRE.G7.CREATI.ACCOUNTS_OF_CREATION.a', 'CRE.G7.CREATI.ACCOUNTS_OF_CREATION.b', 'CRE.G7.CREATI.ACCOUNTS_OF_CREATION.c']::text[], 'The child says the first account (Genesis 1) has God creating in six days and resting on the seventh, with human beings made last in God''s image, and the second (Genesis 2) has the man formed from the dust and given life by God''s breath and placed in the garden of Eden; and names attributes of God (powerful, creator, good, caring, orderly). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'CRE.G7.CREATI.STEWARDSHIP_OVER_CREATIO', 'cre', 7, 'Say what God asked people to do for animals, fish and birds, and how to protect them', ARRAY['CRE.G7.CREATI.STEWARDSHIP_OVER_CREATIO.a', 'CRE.G7.CREATI.STEWARDSHIP_OVER_CREATIO.b']::text[], 'The child says God gave people the duty to rule over and care for animals, fish and birds (Genesis 1:26-28), and names ways to protect them (not hunting illegally, not polluting water, leaving nests, giving shelter and food). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS', 'CRE.G7.CREATI.RESPONSIBILITY_OVER_PLAN', 'cre', 7, 'Say what God asked people to do for plants and how to use them well', ARRAY['CRE.G7.CREATI.RESPONSIBILITY_OVER_PLAN.a', 'CRE.G7.CREATI.RESPONSIBILITY_OVER_PLAN.b', 'CRE.G7.CREATI.RESPONSIBILITY_OVER_PLAN.c']::text[], 'The child says God gave plants for food and asked people to work and take care of the garden (Genesis 1:29 and 2:15), and says caring for plants (planting trees, not cutting without replacing) protects the land and can bring income. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE', 'CRE.G7.CREATI.USE_OF_NATURAL_RESOURCES', 'cre', 7, 'Tell good use from misuse of natural resources', ARRAY['CRE.G7.CREATI.USE_OF_NATURAL_RESOURCES.a', 'CRE.G7.CREATI.USE_OF_NATURAL_RESOURCES.b', 'CRE.G7.CREATI.USE_OF_NATURAL_RESOURCES.c']::text[], 'The child names uses (water for drinking and farming, soil for crops) and misuse (polluting rivers, wasting water, cutting trees without replanting) and the effects (drought, soil erosion, hunger, disease), and says the Bible calls for careful use. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS', 'CRE.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE', 'cre', 7, 'Say what the Bible does for people today', ARRAY['CRE.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.a', 'CRE.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.b', 'CRE.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.c']::text[], 'The child says the Bible teaches about God, guides how to live, comforts and gives hope, and says Christians use it in worship, teaching, prayer and service. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS', 'CRE.G7.THE_BI.DIVISIONS_OF_THE_BIBLE', 'cre', 7, 'Name the two divisions of the Bible and sort books into them', ARRAY['CRE.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.a', 'CRE.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.b']::text[], 'The child says the Bible has two divisions, the Old Testament (39 books) and the New Testament (27 books), says Genesis and Psalms are in the Old, and Matthew and Romans are in the New. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION', 'CRE.G7.THE_BI.BIBLE_TRANSLATION', 'cre', 7, 'Say why and how the Bible was translated', ARRAY['CRE.G7.THE_BI.BIBLE_TRANSLATION.a', 'CRE.G7.THE_BI.BIBLE_TRANSLATION.b', 'CRE.G7.THE_BI.BIBLE_TRANSLATION.c', 'CRE.G7.THE_BI.BIBLE_TRANSLATION.d']::text[], 'The child says the Old Testament was first written mostly in Hebrew and the New Testament in Greek, that the Bible is translated so people can read it in their own language, and that translation helps reading, education and unity. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED', 'CRE.G7.THE_BI.LEADERSHIP_IN_ISRAEL', 'cre', 7, 'Tell how God prepared Moses to lead Israel', ARRAY['CRE.G7.THE_BI.LEADERSHIP_IN_ISRAEL.a', 'CRE.G7.THE_BI.LEADERSHIP_IN_ISRAEL.b']::text[], 'The child says baby Moses was saved in a basket and brought up in Pharaoh''s palace (Exodus 2), that God called him at the burning bush (Exodus 3), that Aaron helped him speak, and that he led the Israelites out of Egypt through the Red Sea at the Exodus. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES', 'CRE.G7.THE_BI.LEADERSHIP_IN_ISRAEL', 'cre', 7, 'Name leadership qualities of Moses', ARRAY['CRE.G7.THE_BI.LEADERSHIP_IN_ISRAEL.c']::text[], 'The child names qualities seen in Moses (obedience to God, humility, courage, patience, prayerfulness, caring for the people) and says leaders of integrity are honest and fair. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY', 'CRE.G7.THE_EA.PROPHECIES_ABOUT_THE_MES', 'cre', 7, 'Match Old Testament prophecies about the Messiah to their fulfilment', ARRAY['CRE.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.a', 'CRE.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.b']::text[], 'The child says Micah 5:2 foretold the Messiah''s birth in Bethlehem, Isaiah 7:14 that a virgin would bear a son called Immanuel, and Isaiah 9:6 names Him Prince of Peace, and that Christians say Jesus fulfilled them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'CRE.G7.THE_EA.JOHN_THE_BAPTIST', 'cre', 7, 'Tell the story and message of John the Baptist', ARRAY['CRE.G7.THE_EA.JOHN_THE_BAPTIST.a', 'CRE.G7.THE_EA.JOHN_THE_BAPTIST.b', 'CRE.G7.THE_EA.JOHN_THE_BAPTIST.d', 'CRE.G7.THE_EA.JOHN_THE_BAPTIST.c']::text[], 'The child says the angel Gabriel told Zechariah that Elizabeth would bear a son called John, that John prepared the way for the Messiah, and that he told people to repent and to share, collect no more tax than was due and not to take by force or accuse falsely (Luke 3:7-14). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH', 'CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_', 'cre', 7, 'Tell the story of the birth and dedication of Jesus', ARRAY['CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.a', 'CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.b', 'CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.c']::text[], 'The child says the angel Gabriel told Mary she would bear Jesus, that Jesus was born in Bethlehem and laid in a manger, that shepherds were told by angels, and that Jesus was dedicated at the Temple in Jerusalem where Simeon and Anna blessed Him (Luke 2). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE', 'CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_', 'cre', 7, 'Tell the story of Jesus in the Temple at twelve', ARRAY['CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.d', 'CRE.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.e']::text[], 'The child says that at twelve Jesus stayed in the Temple in Jerusalem after the Passover feast, that his parents found him after three days among the teachers, that He said He must be in His Father''s house, and that He then went home and obeyed them (Luke 2:41-52). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS', 'CRE.G7.THE_CH.SELECTED_FORMS_OF_WORSHI', 'cre', 7, 'Say what praise, thanksgiving, prayer and fasting are', ARRAY['CRE.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.a', 'CRE.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.b', 'CRE.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.c']::text[], 'The child says praise and thanksgiving honour God for who He is and what He has done (Psalm 100), prayer is talking with God (Matthew 6:9-13), and fasting is going without food for a time to draw near to God (Matthew 6:16-18), and that Jesus taught to pray and fast without showing off. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE', 'CRE.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED', 'cre', 7, 'Say how the church has served in education and health, and the barriers it meets', ARRAY['CRE.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.a', 'CRE.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.b', 'CRE.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.c']::text[], 'The child says churches started many schools, hospitals and clinics in Kenya, and names barriers to mission work (poverty, lack of workers, long distances, differences of belief and conflict) and ways to answer them (giving, training, working together, prayer). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'CRE.G7.CHRIST.HUMAN_SEXUALITY', 'cre', 7, 'Say what human sexuality is and name healthy and unhealthy relationships', ARRAY['CRE.G7.CHRIST.HUMAN_SEXUALITY.a', 'CRE.G7.CHRIST.HUMAN_SEXUALITY.b', 'CRE.G7.CHRIST.HUMAN_SEXUALITY.c', 'CRE.G7.CHRIST.HUMAN_SEXUALITY.d', 'CRE.G7.CHRIST.HUMAN_SEXUALITY.e']::text[], 'The child says human sexuality is part of who we are as male and female, and is to be handled with respect; names healthy relationships (respect, honesty, trust, kindness) and unhealthy ones (pressure, secrecy, force, insults); and says a child who feels unsafe tells a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY', 'CRE.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F', 'cre', 7, 'Tell what the Bible says about marriage and family and what keeps families stable', ARRAY['CRE.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.a', 'CRE.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.b', 'CRE.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.c']::text[], 'The child says the Bible teaches that God made marriage as a lasting union of a man and a woman (Genesis 2:24), and names values that keep a family stable (love, respect, forgiveness, honesty, sharing duties). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE', 'CRE.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA', 'cre', 7, 'Name commonly abused drugs, causes and effects, and safe ways to stay free', ARRAY['CRE.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.a', 'CRE.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.b', 'CRE.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.c', 'CRE.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.e']::text[], 'The child names commonly abused drugs in Kenya (alcohol, bhang, miraa, tobacco), reasons young people try them (peer pressure, curiosity, stress), effects (poor health, poor school work, family conflict), and says to refuse, give reasons and talk to a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.GAMBLING.GAMBLING', 'CRE.G7.CHRIST.GAMBLING', 'cre', 7, 'Name types and effects of gambling and what the Bible teaches about wealth', ARRAY['CRE.G7.CHRIST.GAMBLING.a', 'CRE.G7.CHRIST.GAMBLING.b', 'CRE.G7.CHRIST.GAMBLING.d']::text[], 'The child names types of gambling (betting on games, lotteries, casinos), causes (wanting quick money, peer pressure, advertising) and effects (debt, lost money, family quarrels), and says the Bible teaches to work honestly and that true riches are not money alone (1 Timothy 6:10). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.GAMBLING.MONEY_RICHES', 'CRE.G7.CHRIST.GAMBLING', 'cre', 7, 'Outline the teachings on money, wealth and true riches in the scriptures provided (1 Timothy 6:10, 6:17-19; Proverbs 13:11, 28:20-22; Ephesians 4:28; Matthew 6:19-21; Hebrews 13:5)', ARRAY['CRE.G7.CHRIST.GAMBLING.c', 'CRE.G7.CHRIST.GAMBLING.e']::text[], 'Says that the love of money (not money itself) is a root of all kinds of evil (1 Timothy 6:10), that dishonest money dwindles while money gathered little by little grows (Proverbs 13:11), that one eager to get rich falls into trouble (Proverbs 28:20-22), that a person should work honestly and share (Ephesians 4:28), be content (Hebrews 13:5), and store up treasures in heaven by being rich in good deeds (Matthew 6:19-21; 1 Timothy 6:17-19). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a verse teaches about money","true riches against earthly riches","apply a verse to a money choice"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRE.G7.CHRIST.SOCIAL_MEDIA', 'cre', 7, 'Say how to use social media responsibly and answer cyberbullying', ARRAY['CRE.G7.CHRIST.SOCIAL_MEDIA.a', 'CRE.G7.CHRIST.SOCIAL_MEDIA.b', 'CRE.G7.CHRIST.SOCIAL_MEDIA.c', 'CRE.G7.CHRIST.SOCIAL_MEDIA.d', 'CRE.G7.CHRIST.SOCIAL_MEDIA.e']::text[], 'The child names platforms (WhatsApp, Facebook, TikTok, YouTube), responsible habits (kind words, privacy, not sharing others'' pictures, time limits), misuse (cyberbullying, false news, sharing private information), and says to save the message, not reply in anger and tell a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'skill', 'essential', 'Values in the Ten Commandments, the first list of values a learner meets in CRE. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'skill', 'essential', 'The Bible as God''s word, which CRE studies. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'skill', 'essential', 'Genesis 3 follows the second creation account. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'CRES.G6.CREATI.LEISURE.LEISURE_REST', 'skill', 'essential', 'God''s rest on the seventh day closes the first account. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'skill', 'essential', 'Attributes of God, which the creation accounts show. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'CRES.G5.CREATI.WORK.STEWARDSHIP', 'skill', 'essential', 'Grade 5: the work God gave people over creation. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'CRES.G6.CREATI.LEISURE.LEISURE_USE', 'skill', 'essential', 'Choosing activities that build up rather than harm. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
