INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE.M_CR7_CV_MARKS', 'CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'Thinks CRE is only for passing exams.', '{"question":"Why do we learn CRE?","wrong_answer":"Only to pass exams","correct_answer":"To grow in good values and know God"}'::jsonb, 'Exams are what school rewards, so every subject is seen as a mark.', 'Offer "Only to pass exams" next to the right answer and ask the question again in a new situation.', 'Ask learners to write how one CRE lesson changed what they did that week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE.M_CR7_CV_CHURCH_ONLY', 'CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'Thinks CRE applies only in church.', '{"question":"Where should we show the values learnt in CRE?","wrong_answer":"Only in church","correct_answer":"At home, school and church"}'::jsonb, 'CRE talks about God, and God is linked with church.', 'Offer "Only in church" next to the right answer and ask the question again in a new situation.', 'List places values are needed: home, school, the matatu, online. Match a value to each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE.M_CR7_CV_VALUE_MIX', 'CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'Picks boldness in getting one''s own way as a value, mixing confidence with selfishness, instead of honesty.', '{"question":"Which is a value learnt in CRE?","wrong_answer":"Getting your own way at any cost","correct_answer":"Honesty"}'::jsonb, 'Some values sound alike and the learner picks a word that "sounds strong".', 'Offer "Getting your own way at any cost" beside "Honesty" and ask the child to choose.', 'Sort cards into values and vices; give each value an action that shows it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE.M_CR7_CV_RULES_ONLY', 'CRES.G7.OVERVI.IMPORTANCE_OF_STUDYING_C.CRE_VALUE', 'Thinks CRE is only a list of rules, not also knowing God and growing in character.', '{"question":"What is Christian Religious Education mainly about?","wrong_answer":"Learning rules so as to avoid punishment","correct_answer":"Knowing God through the Bible and growing in values for responsible living"}'::jsonb, 'Many lessons end with "do" and "do not", so the learner hears only rules.', 'Offer "Learning rules so as to avoid punishment" beside "Knowing God through the Bible and growing in values for responsible living" and ask the child to choose.', 'Ask what each lesson taught about God, then what it taught about living. Both together are CRE.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO.M_CR7_CT_SEVEN', 'CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'Says God worked for seven days in Genesis 1, counting the day of rest as a working day.', '{"question":"In how many days did God create in Genesis 1, before resting?","wrong_answer":"Seven days of work","correct_answer":"Six days"}'::jsonb, 'The week has seven days, so the learner counts the rest day as a working day.', 'Offer "Seven days of work" next to the right answer and ask the question again in a new situation.', 'Number Genesis 1 day by day on the board; stop at day six; write "rest" on day seven.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO.M_CR7_CT_DUST', 'CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'Puts man formed from the dust in the first account (Genesis 1), mixing it with the second (Genesis 2:7).', '{"question":"In which account is man formed from the dust?","wrong_answer":"The first account in Genesis 1","correct_answer":"The second account in Genesis 2"}'::jsonb, 'The two accounts are read as one story.', 'Offer "The first account in Genesis 1" next to the right answer and ask the question again in a new situation.', 'Make two columns, Genesis 1 and Genesis 2, and write where each detail comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO.M_CR7_CT_ATTRIBUTE', 'CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'Names God as all-forgiving as an attribute shown in the creation accounts, instead of one the accounts show, such as creator and orderly.', '{"question":"Which attribute of God is shown in Genesis 1 by \"God said... and it was so\"?","wrong_answer":"God forgives sins","correct_answer":"God is all-powerful: he creates by his word"}'::jsonb, 'The learner names any attribute of God, not one the accounts show.', 'Offer "God forgives sins" beside "God is all-powerful: he creates by his word" and ask the child to choose.', 'For each attribute, ask for the verse in Genesis 1-2 that shows it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO.M_CR7_CT_ORDER_MAN', 'CRES.G7.CREATI.ACCOUNTS_OF_CREATION.CREATION_TWO', 'Thinks man was made first in Genesis 1, before plants and animals.', '{"question":"In Genesis 1, on which day were human beings made?","wrong_answer":"On the first day","correct_answer":"On the sixth day, after the plants and animals"}'::jsonb, 'In Genesis 2 the man is made before the plants appear, and the orders mix.', 'Offer "On the first day" beside "On the sixth day, after the plants and animals" and ask the child to choose.', 'Write Genesis 1 in six boxes and Genesis 2 as a separate story; note the difference as one of the points to discuss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS.M_CR7_SA_RULE_HARM', 'CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'Reads "rule over" (Genesis 1:28) as permission to use animals in any way, even cruelly.', '{"question":"What does \"rule over the fish, the birds and every living creature\" mean?","wrong_answer":"People may treat animals any way they like","correct_answer":"Care for them as God''s caretakers"}'::jsonb, 'The word "rule" is heard as power to do anything.', 'Offer "People may treat animals any way they like" beside "Care for them as God''s caretakers" and ask the child to choose.', 'Read Genesis 1:28 with 2:15: rule as God''s caretaker who will answer to him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS.M_CR7_SA_PROTECT', 'CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'Thinks killing birds with a catapult for fun is harmless because birds are many.', '{"question":"Boys kill birds with a catapult for fun. Is this good stewardship?","wrong_answer":"Yes, there are many birds","correct_answer":"No: it harms God''s creatures for no need"}'::jsonb, 'The learner sees some harm as normal, such as killing birds for fun.', 'Offer "Yes, there are many birds" beside "No: it harms God''s creatures for no need" and ask the child to choose.', 'List daily acts that harm animals and the caring choice for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS.M_CR7_SA_NOT_MINE', 'CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'Thinks creation belongs to people.', '{"question":"To whom does creation belong?","wrong_answer":"To people to use as they wish","correct_answer":"To God, who gave us the care of it"}'::jsonb, 'Owning a cow or a dog feels like full ownership.', 'Offer "To people to use as they wish" next to the right answer and ask the question again in a new situation.', 'Read Psalm 24:1: the earth is the Lord''s. We care for what is his.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS.M_CR7_SA_POACH_OK', 'CRES.G7.CREATI.STEWARDSHIP_OVER_CREATIO.STEWARD_ANIMALS', 'Thinks poaching wild animals is fine if a family is poor.', '{"question":"A man kills elephants for their tusks to feed his family. What does stewardship teach?","wrong_answer":"It is fine because he is poor","correct_answer":"It is wrong: wildlife is God''s creation and protected by law"}'::jsonb, 'Poverty makes any income seem justified.', 'Offer "It is fine because he is poor" beside "It is wrong: wildlife is God''s creation and protected by law" and ask the child to choose.', 'Discuss honest work and the Kenya Wildlife Service; God''s care for creatures (Genesis 1:21-22).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS.M_CR7_SP_WASTE', 'CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS', 'Thinks cutting trees for charcoal without replanting does no harm, because there are many trees.', '{"question":"A family cuts trees for charcoal every month. What does stewardship ask?","wrong_answer":"Nothing: there are many trees","correct_answer":"Plant more trees than are cut"}'::jsonb, 'Trees are everywhere and the learner does not see them running out.', 'Offer "Nothing: there are many trees" beside "Plant more trees than are cut" and ask the child to choose.', 'Show the cost: a tree takes years to grow. Plan a "cut one, plant two" rule for the school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS.M_CR7_SP_FOOD', 'CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS', 'Thinks God gave plants only for beauty, missing Genesis 1:29: plants for food.', '{"question":"Why did God give plants, according to Genesis 1:29?","wrong_answer":"Only to make the earth beautiful","correct_answer":"For food, as well as beauty"}'::jsonb, 'The learner remembers only the beauty of Eden.', 'Offer "Only to make the earth beautiful" beside "For food, as well as beauty" and ask the child to choose.', 'Read Genesis 1:29 and 2:9: plants for food and beauty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS.M_CR7_SP_INCOME', 'CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS', 'Thinks caring for plants is only about food and cannot earn an income.', '{"question":"How can responsible use of plants help the economy?","wrong_answer":"It cannot; plants are only food","correct_answer":"Cash crops, timber and fruit bring income and jobs"}'::jsonb, 'The learner thinks farming is for food only and does not see markets.', 'Offer "It cannot; plants are only food" beside "Cash crops, timber and fruit bring income and jobs" and ask the child to choose.', 'Name crops grown for sale in the area and what the money pays for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS.M_CR7_SP_BURN_BUSH', 'CRES.G7.CREATI.RESPONSIBILITY_OVER_PLAN.STEWARD_PLANTS', 'Thinks burning bushes to clear land is good stewardship because it is quick.', '{"question":"A farmer burns the bush to clear land every year. Is this responsible use of plants?","wrong_answer":"Yes, it is the quickest way","correct_answer":"No: it kills soil life and causes erosion; there are better ways"}'::jsonb, 'Burning is common and seen as normal.', 'Offer "Yes, it is the quickest way" beside "No: it kills soil life and causes erosion; there are better ways" and ask the child to choose.', 'List effects of burning on soil and wildlife; compare with clearing and composting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE.M_CR7_RU_MISUSE', 'CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE', 'Thinks pouring waste into a river is fine because the water carries it away.', '{"question":"A factory pours waste into a river. What is this?","wrong_answer":"Good use: the river carries it away","correct_answer":"Misuse: it poisons water for fish and people"}'::jsonb, 'Waste poured out of sight seems to disappear.', 'Offer "Good use: the river carries it away" beside "Misuse: it poisons water for fish and people" and ask the child to choose.', 'Follow the waste: river, fish, people downstream who drink it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE.M_CR7_RU_EFFECT', 'CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE', 'Thinks cutting trees has no effect on the land, missing soil erosion and drought.', '{"question":"Which is an effect of cutting trees without replanting?","wrong_answer":"More rain forever","correct_answer":"Soil erosion and drought"}'::jsonb, 'The learner has not linked trees and rain.', 'Offer "More rain forever" next to the right answer and ask the question again in a new situation.', 'Show a picture of a bare hillside after rain: gullies, mud in the river.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE.M_CR7_RU_GOOD', 'CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE', 'Thinks a bare, swept field is good use of soil, though it washes away in rain.', '{"question":"Which is good use of soil?","wrong_answer":"Sweeping it bare so it looks tidy","correct_answer":"Keeping it covered with crops or mulch"}'::jsonb, 'Bare soil looks tidy and "clean".', 'Offer "Sweeping it bare so it looks tidy" beside "Keeping it covered with crops or mulch" and ask the child to choose.', 'Show soil cover (mulch, crops) and explain it holds the soil in rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE.M_CR7_RU_ENDLESS', 'CRES.G7.CREATI.USE_OF_NATURAL_RESOURCES.RESOURCES_USE', 'Thinks natural resources such as water and forests can never run out.', '{"question":"Can natural resources such as water and forests run out?","wrong_answer":"No, God made them endless","correct_answer":"Yes, if they are misused; we must use them well"}'::jsonb, 'The learner reasons that what God made cannot fail.', 'Offer "No, God made them endless" beside "Yes, if they are misused; we must use them well" and ask the child to choose.', 'Show a dried river or a cleared forest in Kenya; read Genesis 2:15 as a call to care.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS.M_CR7_BF_STORY_ONLY', 'CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS', 'Thinks the Bible is only a book of old stories, missing that it also teaches, guides and comforts.', '{"question":"What does the Bible do for people?","wrong_answer":"Only tells old stories","correct_answer":"Teaches, guides and gives hope"}'::jsonb, 'Bible lessons in lower grades were mostly stories.', 'Offer "Only tells old stories" next to the right answer and ask the question again in a new situation.', 'Show other parts: law, songs, wisdom, letters, prophecy. Ask what each does today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS.M_CR7_BF_CHURCH_ONLY', 'CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS', 'Thinks only church leaders may read and explain the Bible.', '{"question":"Who may read the Bible?","wrong_answer":"Only church leaders","correct_answer":"Everyone who wishes to"}'::jsonb, 'The learner sees leaders reading in church and few others.', 'Offer "Only church leaders" next to the right answer and ask the question again in a new situation.', 'Show family devotions and school assemblies: everyone may read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS.M_CR7_BF_SERVICE', 'CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS', 'Does not link Christian services such as hospitals and children''s homes with the Bible''s teaching.', '{"question":"Why do many churches run hospitals and children''s homes?","wrong_answer":"Only to make money","correct_answer":"Because the Bible teaches care for the sick and needy (Matthew 25:35-36)"}'::jsonb, 'The learner does not see the link between reading and serving.', 'Offer "Only to make money" beside "Because the Bible teaches care for the sick and needy (Matthew 25:35-36)" and ask the child to choose.', 'Name services inspired by the Bible: hospitals, schools, children''s homes, prison visits (Matthew 25:35-36).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS.M_CR7_BF_SPIRIT_ONLY', 'CRES.G7.THE_BI.FUNCTIONS_OF_THE_BIBLE.BIBLE_FUNCTIONS', 'Thinks the Bible helps only the spirit, not the whole person (mind, body, relationships).', '{"question":"How does the Bible promote holistic growth?","wrong_answer":"It helps only the soul","correct_answer":"It guides the mind, body, relationships and spirit"}'::jsonb, 'The word "holistic" is new and the learner pictures only prayer.', 'Offer "It helps only the soul" beside "It guides the mind, body, relationships and spirit" and ask the child to choose.', 'Draw a person with four parts (spiritual, mental, physical, social) and find a verse for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS.M_CR7_BD_NUMBER', 'CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS', 'Says the Bible has three divisions, counting the books some Bibles add, instead of the two Testaments.', '{"question":"How many divisions has the Bible?","wrong_answer":"Three","correct_answer":"Two: Old and New Testament"}'::jsonb, 'Some Bibles include extra books between the Testaments, and the learner counts them as a third division.', 'Offer "Three" next to the right answer and ask the question again in a new situation.', 'Name the two divisions; note that some Bibles add the deuterocanonical books, which the learner''s church will explain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS.M_CR7_BD_SORT_OT', 'CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS', 'Puts Genesis in the New Testament, linking "new" with "beginning".', '{"question":"In which Testament is Genesis?","wrong_answer":"The New Testament","correct_answer":"The Old Testament"}'::jsonb, 'Genesis tells of beginnings, and the learner links "new" with "beginning".', 'Offer "The New Testament" next to the right answer and ask the question again in a new situation.', 'Remember: Old Testament before Jesus, New Testament from Jesus. Genesis is the start of the Old.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS.M_CR7_BD_SORT_NT', 'CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS', 'Puts Matthew in the Old Testament because it quotes the prophets often.', '{"question":"In which Testament is Matthew?","wrong_answer":"The Old Testament","correct_answer":"The New Testament"}'::jsonb, 'Matthew quotes the Old Testament often, and the learner places it there.', 'Offer "The Old Testament" next to the right answer and ask the question again in a new situation.', 'Matthew opens the New Testament with Jesus'' family line. Open the Bible to show it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS.M_CR7_BD_GROUPS', 'CRES.G7.THE_BI.DIVISIONS_OF_THE_BIBLE.BIBLE_DIVISIONS', 'Mixes the groups of books, putting the Gospels among the letters or Psalms among the prophets.', '{"question":"In which group of books is Psalms?","wrong_answer":"The Prophets","correct_answer":"Poetry and Wisdom"}'::jsonb, 'David spoke of the future in the Psalms and the learner links that with prophecy.', 'Offer "The Prophets" beside "Poetry and Wisdom" and ask the child to choose.', 'Draw a library: Law, History, Poetry and Wisdom, Prophets; Gospels, Acts, Letters, Revelation. Place books on shelves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION.M_CR7_BT_LANGUAGE', 'CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION', 'Says most of the New Testament was first written in Latin instead of Greek.', '{"question":"In which language was most of the New Testament first written?","wrong_answer":"Latin","correct_answer":"Greek"}'::jsonb, 'Latin is linked with old church writings.', 'Offer "Latin" next to the right answer and ask the question again in a new situation.', 'Write the three original languages: Hebrew (most of the Old Testament), Aramaic (parts), Greek (New Testament).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION.M_CR7_BT_WHY', 'CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION', 'Does not see that the Bible is translated so people can read it in their own language.', '{"question":"Why is the Bible translated into Kenyan languages?","wrong_answer":"To make the church leaders important","correct_answer":"So people can read and understand it in their own language"}'::jsonb, 'The learner has heard that translation is difficult and confuses difficulty with purpose.', 'Offer "To make the church leaders important" beside "So people can read and understand it in their own language" and ask the child to choose.', 'Ask: who can read Greek? Translation is so everyone can read in their own language.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION.M_CR7_BT_EFFECT', 'CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION', 'Thinks translation has no effect beyond the church, missing literacy and written local languages.', '{"question":"Which is a social effect of translating the Bible into local languages?","wrong_answer":"None outside church","correct_answer":"More people learned to read and local languages were written down"}'::jsonb, 'The learner thinks only of church effects, not social ones.', 'Offer "None outside church" beside "More people learned to read and local languages were written down" and ask the child to choose.', 'List effects: literacy, schools, written local languages, preserved culture, jobs in printing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION.M_CR7_BT_VERSION_DIFFERENT_BIBLE', 'CRES.G7.THE_BI.BIBLE_TRANSLATION.BIBLE_TRANSLATION', 'Thinks different versions (such as the Good News Bible and the King James) are different Bibles with different messages.', '{"question":"What is a Bible version?","wrong_answer":"A different Bible with a different message","correct_answer":"A translation of the same Bible in particular words"}'::jsonb, 'Different covers and words look like different books.', 'Offer "A different Bible with a different message" beside "A translation of the same Bible in particular words" and ask the child to choose.', 'Read John 3:16 in two English versions: same meaning, different words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED.M_CR7_MP_PALACE', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED', 'Says Moses grew up in an Israelite village instead of Pharaoh''s palace.', '{"question":"Where did Moses grow up?","wrong_answer":"In a village of Israel","correct_answer":"In Pharaoh''s palace"}'::jsonb, 'The learner knows Moses was a Hebrew and pictures him among his people.', 'Offer "In a village of Israel" next to the right answer and ask the question again in a new situation.', 'Read Exodus 2:10: he became the son of Pharaoh''s daughter. God prepared him in the palace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED.M_CR7_MP_BUSH', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED', 'Places God''s call of Moses at the Red Sea instead of the burning bush on Mount Horeb.', '{"question":"Where did God call Moses?","wrong_answer":"At the Red Sea","correct_answer":"At the burning bush"}'::jsonb, 'The Red Sea is the most famous Moses scene.', 'Offer "At the Red Sea" next to the right answer and ask the question again in a new situation.', 'Order the events: palace, flight to Midian, the burning bush (call), back to Egypt, the Red Sea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED.M_CR7_MP_AARON', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED', 'Names Joshua instead of Aaron as the one who spoke for Moses before Pharaoh.', '{"question":"Who helped Moses speak to Pharaoh?","wrong_answer":"Joshua","correct_answer":"Aaron"}'::jsonb, 'Joshua is Moses'' best-known helper.', 'Offer "Joshua" next to the right answer and ask the question again in a new situation.', 'Read Exodus 4:14-16: Aaron to speak for Moses. Joshua led the fighting men later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES.M_CR7_MQ_PRIDE', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES', 'Names pride as one of Moses'' qualities, though Numbers 12:3 calls him very humble.', '{"question":"Which quality did Moses show?","wrong_answer":"Pride","correct_answer":"Humility and obedience to God"}'::jsonb, 'Leaders the learner sees on TV often act proud.', 'Offer "Pride" next to the right answer and ask the question again in a new situation.', 'Read Numbers 12:3: Moses was very humble. List his qualities from the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES.M_CR7_MQ_LEADER', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES', 'Thinks a good leader must be cunning and bend the truth to get things done.', '{"question":"Exodus 18:21 says leaders should be...","wrong_answer":"Clever enough to bend the truth","correct_answer":"Trustworthy, God-fearing and hating dishonest gain"}'::jsonb, 'The learner has heard that leaders must be tough or cunning to win.', 'Offer "Clever enough to bend the truth" beside "Trustworthy, God-fearing and hating dishonest gain" and ask the child to choose.', 'Compare Moses'' honesty and fairness (Exodus 18:21: trustworthy men who hate dishonest gain) with leaders who cheat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES.M_CR7_MQ_FEAR', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES', 'Thinks Moses led alone, missing Aaron, Jethro''s advice and the appointed judges.', '{"question":"Who helped Moses lead?","wrong_answer":"Nobody helped him","correct_answer":"God and people such as Aaron"}'::jsonb, 'Great leaders are pictured as doing everything alone.', 'Offer "Nobody helped him" next to the right answer and ask the question again in a new situation.', 'Read Exodus 18:17-24: Jethro advised Moses to share the work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED.M_CR7_MP_MIDIAN', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_PREPARED', 'Forgets the forty years in Midian as a shepherd, part of God''s preparation.', '{"question":"What did Moses do in Midian before God called him (Exodus 3:1)?","wrong_answer":"He ruled as a prince","correct_answer":"He looked after the flock of Jethro, his father-in-law"}'::jsonb, 'The learner jumps from the palace to the call.', 'Offer "He ruled as a prince" beside "He looked after the flock of Jethro, his father-in-law" and ask the child to choose.', 'Draw Moses'' life in three parts: palace, shepherd in Midian, leader. Ask what a shepherd learns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES.M_CR7_MQ_NEVER_AFRAID', 'CRES.G7.THE_BI.LEADERSHIP_IN_ISRAEL.MOSES_QUALITIES', 'Thinks Moses was never afraid or unsure.', '{"question":"How did Moses first answer God''s call (Exodus 4:10-13)?","wrong_answer":"Gladly and without fear","correct_answer":"He said he was slow of speech and asked God to send someone else"}'::jsonb, 'The learner expects great leaders to be fearless.', 'Offer "Gladly and without fear" beside "He said he was slow of speech and asked God to send someone else" and ask the child to choose.', 'Read Exodus 4:10-13. God used Moses even with his fears: obedience grows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY.M_CR7_MS_BETHLEHEM', 'CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY', 'Says Micah 5:2 named Nazareth as the Messiah''s birthplace instead of Bethlehem.', '{"question":"Which town did Micah 5:2 name as the Messiah''s birthplace?","wrong_answer":"Nazareth","correct_answer":"Bethlehem"}'::jsonb, 'Jesus is called "of Nazareth", so the learner thinks the prophecy named it.', 'Offer "Nazareth" next to the right answer and ask the question again in a new situation.', 'Read Micah 5:2 and Matthew 2:5-6 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY.M_CR7_MS_VIRGIN', 'CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY', 'Names Moses as the prophet of the virgin birth instead of Isaiah (Isaiah 7:14).', '{"question":"Which prophet said a virgin would bear a son called Immanuel?","wrong_answer":"Moses","correct_answer":"Isaiah"}'::jsonb, 'Moses is the best-known Old Testament figure.', 'Offer "Moses" next to the right answer and ask the question again in a new situation.', 'Make a card for each prophecy with its prophet: Isaiah 7:14 (virgin, Immanuel), Micah 5:2 (Bethlehem), Isaiah 9:6 (child, Prince of Peace).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY.M_CR7_MS_FULFIL', 'CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY', 'Thinks a fulfilled prophecy is one that was cancelled or forgotten.', '{"question":"What does it mean that a prophecy was fulfilled?","wrong_answer":"It was cancelled","correct_answer":"It came true"}'::jsonb, 'The learner does not know the word "fulfil".', 'Offer "It was cancelled" beside "It came true" and ask the child to choose.', 'Show: a promise made, then kept. Prophecy said; Jesus fulfilled.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY.M_CR7_MS_IMMANUEL', 'CRES.G7.THE_EA.PROPHECIES_ABOUT_THE_MES.MESSIAH_PROPHECY', 'Thinks Immanuel is another man, not a name for Jesus meaning "God with us".', '{"question":"What does the name Immanuel mean (Matthew 1:23)?","wrong_answer":"A second son of Mary","correct_answer":"God with us"}'::jsonb, 'An unfamiliar name sounds like a different person.', 'Offer "A second son of Mary" beside "God with us" and ask the child to choose.', 'Read Matthew 1:23, where the meaning is given.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_CR7_JB_PARENTS', 'CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Gives Joseph and Mary as John the Baptist''s parents instead of Zechariah and Elizabeth.', '{"question":"Who were the parents of John the Baptist?","wrong_answer":"Joseph and Mary","correct_answer":"Zechariah and Elizabeth"}'::jsonb, 'The two annunciation stories are side by side in Luke 1.', 'Offer "Joseph and Mary" next to the right answer and ask the question again in a new situation.', 'Draw two families: Zechariah and Elizabeth (John); Joseph and Mary (Jesus).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_CR7_JB_ROLE', 'CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John was the Messiah.', '{"question":"What was John''s role?","wrong_answer":"He was the Messiah","correct_answer":"He prepared the way for the Messiah"}'::jsonb, 'People in Luke 3:15 wondered the same, and John''s fame confuses the learner.', 'Offer "He was the Messiah" next to the right answer and ask the question again in a new situation.', 'Read Luke 3:15-16: John said one more powerful was coming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_CR7_JB_MESSAGE', 'CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John told people that being children of Abraham was enough, missing his call to repent and bear fruit (Luke 3:8).', '{"question":"What did John say about being children of Abraham (Luke 3:8)?","wrong_answer":"That it was enough to be saved","correct_answer":"That they must produce fruit in keeping with repentance"}'::jsonb, 'The learner remembers the crowd but not what John asked.', 'Offer "That it was enough to be saved" beside "That they must produce fruit in keeping with repentance" and ask the child to choose.', 'Chart Luke 3:10-14: crowd, share; tax collectors, honesty; soldiers, no extortion, contentment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_CR7_JB_LAMB_LITERAL', 'CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Takes "the Lamb of God" (John 1:29) as a real lamb or a pet.', '{"question":"What did John mean when he called Jesus \"the Lamb of God, who takes away the sin of the world\"?","wrong_answer":"Jesus looked after lambs","correct_answer":"Jesus would be the sacrifice that takes away sin"}'::jsonb, 'The learner takes the picture word by word.', 'Offer "Jesus looked after lambs" beside "Jesus would be the sacrifice that takes away sin" and ask the child to choose.', 'Link with the lambs sacrificed in the temple and at Passover. Jesus would give his life for sin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_CR7_JB_GREATER', 'CRES.G7.THE_EA.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John said he was greater than the one coming after him.', '{"question":"In Luke 3:16, what did John say about the one coming after him?","wrong_answer":"That John was greater","correct_answer":"That he was more powerful, and John was not worthy to untie his sandals"}'::jsonb, 'The learner thinks the one who comes first is the greater.', 'Offer "That John was greater" beside "That he was more powerful, and John was not worthy to untie his sandals" and ask the child to choose.', 'Read Luke 3:16 and John 1:30: "he was before me". Act untying sandals, a servant''s job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH.M_CR7_JBR_PLACE', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH', 'Says Jesus was born in Nazareth, his hometown, instead of Bethlehem.', '{"question":"Where was Jesus born?","wrong_answer":"Nazareth","correct_answer":"Bethlehem"}'::jsonb, 'Jesus is called Jesus of Nazareth.', 'Offer "Nazareth" next to the right answer and ask the question again in a new situation.', 'Read Luke 2:4-7: from Nazareth to Bethlehem for the census.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH.M_CR7_JBR_ANGEL', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH', 'Names Michael instead of Gabriel as the angel who came to Mary.', '{"question":"Which angel told Mary she would bear Jesus?","wrong_answer":"Michael","correct_answer":"Gabriel"}'::jsonb, 'Michael is the angel named in songs and other books.', 'Offer "Michael" next to the right answer and ask the question again in a new situation.', 'Read Luke 1:26: Gabriel. He also went to Zechariah.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH.M_CR7_JBR_DEDICATION', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH', 'Places Jesus'' dedication in the River Jordan, mixing it with his baptism as an adult, instead of the temple in Jerusalem.', '{"question":"Where was baby Jesus dedicated?","wrong_answer":"In the River Jordan","correct_answer":"In the Temple at Jerusalem"}'::jsonb, 'Dedication and baptism are both church ceremonies for babies or new believers.', 'Offer "In the River Jordan" next to the right answer and ask the question again in a new situation.', 'Read Luke 2:22-24: in the temple at Jerusalem, with an offering of two doves. Jesus'' baptism came at about thirty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE.M_CR7_JT_AGE', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE', 'Says Jesus was six when he stayed in the temple instead of twelve.', '{"question":"How old was Jesus when He stayed in the Temple?","wrong_answer":"Six","correct_answer":"Twelve"}'::jsonb, 'The learner pictures a small child getting lost.', 'Offer "Six" next to the right answer and ask the question again in a new situation.', 'Read Luke 2:42: twelve years old, going up for the Passover.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE.M_CR7_JT_DAYS', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE', 'Says his parents found him after one day instead of three days.', '{"question":"After how many days did His parents find Him?","wrong_answer":"One day","correct_answer":"Three days"}'::jsonb, 'The learner thinks parents would notice at once.', 'Offer "One day" next to the right answer and ask the question again in a new situation.', 'Read 2:44-46: a day''s journey before they noticed, then three days searching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE.M_CR7_JT_HOME', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE', 'Thinks He did not obey.', '{"question":"What did Jesus do after being found?","wrong_answer":"Stayed in the Temple","correct_answer":"Went home and obeyed them"}'::jsonb, 'Jesus said he must be in his Father''s house, so the learner thinks he stayed.', 'Offer "Stayed in the Temple" next to the right answer and ask the question again in a new situation.', 'Read 2:51: he went down with them to Nazareth and was obedient to them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH.M_CR7_JBR_SIMEON', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_BIRTH', 'Forgets Simeon and Anna, who recognised the baby at the dedication.', '{"question":"Who took baby Jesus in his arms in the temple and praised God (Luke 2:25-28)?","wrong_answer":"The high priest Caiaphas","correct_answer":"Simeon, a righteous and devout man"}'::jsonb, 'Caiaphas is the priest the learner knows from Easter.', 'Offer "The high priest Caiaphas" beside "Simeon, a righteous and devout man" and ask the child to choose.', 'Read Luke 2:25-38 and draw Simeon and Anna with the baby.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE.M_CR7_JT_TEACHING', 'CRES.G7.THE_EA.THE_BIRTH_AND_CHILDHOOD_.JESUS_TEMPLE', 'Thinks the boy Jesus was lecturing the teachers like a preacher, missing that he listened and asked questions.', '{"question":"What was Jesus doing in the temple courts (Luke 2:46)?","wrong_answer":"Preaching a sermon to the crowd","correct_answer":"Sitting among the teachers, listening and asking questions"}'::jsonb, 'The learner expects the Son of God to teach at once.', 'Offer "Preaching a sermon to the crowd" beside "Sitting among the teachers, listening and asking questions" and ask the child to choose.', 'Read Luke 2:46-47 and underline "listening" and "asking questions".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS.M_CR7_WF_FASTING', 'CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS', 'Thinks fasting should be shown to others to prove one''s faith, against Matthew 6:16-18.', '{"question":"How should one fast, as Jesus taught?","wrong_answer":"Showing everyone","correct_answer":"Quietly, without showing off"}'::jsonb, 'Fasting in public seems to show strong faith.', 'Offer "Showing everyone" next to the right answer and ask the question again in a new situation.', 'Read Matthew 6:16-18: wash your face; fast for your Father who sees in secret.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS.M_CR7_WF_PRAYER', 'CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS', 'Thinks prayer is only asking God for things, missing praise, confession and thanksgiving.', '{"question":"What is prayer?","wrong_answer":"Only asking for things","correct_answer":"Talking with God"}'::jsonb, 'Much prayer the learner hears is asking.', 'Offer "Only asking for things" next to the right answer and ask the question again in a new situation.', 'List four parts of prayer: praise, confession, thanksgiving, asking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS.M_CR7_WF_THANKS', 'CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS', 'Thinks thanksgiving is only for good times, missing 1 Thessalonians 5:18: give thanks in all circumstances.', '{"question":"When should Christians give thanks, according to 1 Thessalonians 5:18?","wrong_answer":"Only when things go well","correct_answer":"In all circumstances"}'::jsonb, 'The learner mixes thanksgiving with petitions made in hard times.', 'Offer "Only when things go well" beside "In all circumstances" and ask the child to choose.', 'Read Psalm 100:4 and 1 Thessalonians 5:18: thank God in all circumstances.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS.M_CR7_WF_FAST_DIET', 'CRES.G7.THE_CH.SELECTED_FORMS_OF_WORSHI.WORSHIP_FORMS', 'Thinks fasting is only going without food to lose weight, not a time of prayer.', '{"question":"What is Christian fasting?","wrong_answer":"Skipping meals to lose weight","correct_answer":"Going without food for a time to pray and seek God"}'::jsonb, 'The learner knows skipping meals as dieting.', 'Offer "Skipping meals to lose weight" beside "Going without food for a time to pray and seek God" and ask the child to choose.', 'Read Matthew 6:16-18 and Acts 13:2-3: fasting with prayer and worship.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE.M_CR7_CS_SCHOOLS', 'CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE', 'Thinks the church did not start schools or hospitals in Kenya.', '{"question":"What did the Church start in Kenya?","wrong_answer":"No schools or hospitals","correct_answer":"Many schools and hospitals"}'::jsonb, 'The learner sees schools run by government and does not know their history.', 'Offer "No schools or hospitals" next to the right answer and ask the question again in a new situation.', 'List local schools and hospitals with church names (mission hospitals, church-sponsored schools).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE.M_CR7_CS_BARRIER', 'CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE', 'Names having enough workers as a barrier to mission work, mixing barriers with strengths.', '{"question":"Which is a barrier to mission work?","wrong_answer":"Enough workers","correct_answer":"Poverty and long distances"}'::jsonb, 'The learner does not know what a barrier means.', 'Offer "Enough workers" next to the right answer and ask the question again in a new situation.', 'Explain barrier as something that blocks; list poverty, distance, insecurity, few workers, language.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE.M_CR7_CS_SOLUTION', 'CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE', 'Thinks the answer to barriers in mission work is to stop the work.', '{"question":"Which is a way to answer the barriers?","wrong_answer":"Giving up the work","correct_answer":"Training workers and working together"}'::jsonb, 'Hard problems make giving up seem sensible.', 'Offer "Giving up the work" next to the right answer and ask the question again in a new situation.', 'Match each barrier with a solution: training, partnerships, funding, translation, security.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE.M_CR7_CS_PAST_ONLY', 'CRES.G7.THE_CH.ROLE_OF_THE_CHURCH_IN_ED.CHURCH_SERVICE', 'Thinks the church helped in education and health only in the past, not today.', '{"question":"Does the church still contribute to education and health in Kenya today?","wrong_answer":"No, that was only long ago","correct_answer":"Yes: it sponsors schools, runs hospitals and clinics, and supports the needy"}'::jsonb, 'History lessons place missionaries in the past.', 'Offer "No, that was only long ago" beside "Yes: it sponsors schools, runs hospitals and clinics, and supports the needy" and ask the child to choose.', 'Find a church-sponsored school or mission hospital near the school today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS.M_CR7_SB_SHAME', 'CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'Thinks a child should keep unsafe touch secret.', '{"question":"What should a child do if someone makes them feel unsafe?","wrong_answer":"Keep it secret","correct_answer":"Tell a trusted adult"}'::jsonb, 'Shame and fear of blame keep learners silent.', 'Offer "Keep it secret" next to the right answer and ask the question again in a new situation.', 'Name trusted adults and say clearly: it is never the young person''s fault; telling is right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS.M_CR7_SB_HEALTHY', 'CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'Thinks pressure to prove love is part of a healthy relationship.', '{"question":"A boyfriend says \"if you love me you will prove it\". Is this healthy?","wrong_answer":"Yes, that is what love is","correct_answer":"No: pressure is a sign of an unhealthy relationship"}'::jsonb, 'Pressure can look like love in films.', 'Offer "Yes, that is what love is" beside "No: pressure is a sign of an unhealthy relationship" and ask the child to choose.', 'Sort cards: respect, honesty, trust, parents know (healthy); pressure, secrets, gifts for favours (unhealthy).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS.M_CR7_SB_PART', 'CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'Thinks sexuality is only about the body.', '{"question":"What is human sexuality?","wrong_answer":"Only the body parts","correct_answer":"Part of who we are as male and female"}'::jsonb, 'The word sexuality is heard only as body parts or sex.', 'Offer "Only the body parts" next to the right answer and ask the question again in a new situation.', 'Explain sexuality as being made male and female in God''s image (Genesis 1:27), with feelings, relationships and roles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS.M_CR7_SB_NO_CONSEQUENCE', 'CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'Thinks sex before marriage has no consequences if no one finds out.', '{"question":"Name one consequence of sex before marriage.","wrong_answer":"None, if no one finds out","correct_answer":"Early pregnancy, infections, dropping out of school, guilt and broken trust"}'::jsonb, 'The learner thinks consequences come only from being caught.', 'Offer "None, if no one finds out" beside "Early pregnancy, infections, dropping out of school, guilt and broken trust" and ask the child to choose.', 'List consequences in four groups: health, school, family, faith. Read 1 Corinthians 6:18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS.M_CR7_SB_CHASTE_IMPOSSIBLE', 'CRES.G7.CHRIST.HUMAN_SEXUALITY.SEXUALITY_BASICS', 'Thinks no young person can stay chaste until marriage, so the teaching is pointless.', '{"question":"Is it possible for a young person to remain chaste until marriage?","wrong_answer":"No, nobody can","correct_answer":"Yes: with God''s help, good friends, self-control and avoiding tempting places"}'::jsonb, 'Media and peers say "everyone is doing it".', 'Offer "No, nobody can" beside "Yes: with God''s help, good friends, self-control and avoiding tempting places" and ask the child to choose.', 'Read 1 Thessalonians 4:3-4 and Philippians 4:8. List the skills that help: self-control, assertiveness, good friends, prayer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY.M_CR7_MF_GENESIS', 'CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY', 'Thinks Genesis 2:24 says a man leaves his wife, mixing who is left (father and mother) with who he is joined to.', '{"question":"What does Genesis 2:24 say a man does?","wrong_answer":"Leaves his wife","correct_answer":"Is joined to his wife"}'::jsonb, '"Leave" in the verse is remembered without what follows.', 'Offer "Leaves his wife" next to the right answer and ask the question again in a new situation.', 'Read Genesis 2:24 in full: leave father and mother, be united to his wife.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY.M_CR7_MF_VALUE', 'CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY', 'Picks keeping secrets from each other as a value that keeps families stable, instead of love, honesty and forgiveness.', '{"question":"Which value keeps a family stable?","wrong_answer":"Keeping secrets from each other","correct_answer":"Love, honesty and forgiveness"}'::jsonb, 'The learner picks a word without thinking how it works in a home.', 'Offer "Keeping secrets from each other" beside "Love, honesty and forgiveness" and ask the child to choose.', 'For each value, give a family scene that shows it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY.M_CR7_MF_LASTING', 'CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY', 'Thinks God planned marriage to last only a short time, missing Mark 10:9.', '{"question":"How did God plan marriage?","wrong_answer":"To last a short time","correct_answer":"To be a lasting union"}'::jsonb, 'The learner sees marriages break and thinks it is the plan.', 'Offer "To last a short time" next to the right answer and ask the question again in a new situation.', 'Read Mark 10:9: what God has joined, let no one separate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY.M_CR7_MF_CHURCH_ROLE', 'CRES.G7.CHRIST.CHRISTIAN_MARRIAGE_AND_F.MARRIAGE_FAMILY', 'Thinks the church has no part in preparing young people for marriage.', '{"question":"How does the church promote values among young people before marriage?","wrong_answer":"It does nothing until the wedding","correct_answer":"Through youth programmes, teaching, mentorship and pre-marriage counselling"}'::jsonb, 'The learner sees the church only at the wedding.', 'Offer "It does nothing until the wedding" beside "Through youth programmes, teaching, mentorship and pre-marriage counselling" and ask the child to choose.', 'List church youth activities and what values they teach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE.M_CR7_DA_DRUG', 'CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE', 'Thinks alcohol and cigarettes are not drugs because they are sold in shops.', '{"question":"Which of these is a commonly abused drug?","wrong_answer":"None that are sold in shops","correct_answer":"Alcohol"}'::jsonb, 'Some abused substances are legal and sold openly, so the learner does not count them.', 'Offer "None that are sold in shops" beside "Alcohol" and ask the child to choose.', 'List commonly abused substances in Kenya: alcohol, tobacco, bhang, miraa, glue, prescription pills. Legal does not mean safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE.M_CR7_DA_EFFECT', 'CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE', 'Thinks drugs make a person more relaxed and confident with no lasting harm.', '{"question":"Which is an effect of drug abuse on the family?","wrong_answer":"Everyone is more relaxed","correct_answer":"Money problems, quarrels and violence"}'::jsonb, 'Adverts and friends show drugs as fun and relaxing.', 'Offer "Everyone is more relaxed" beside "Money problems, quarrels and violence" and ask the child to choose.', 'Chart effects on the person (health, school, crime) and on the family (money, violence, shame).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE.M_CR7_DA_REFUSE', 'CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE', 'Thinks giving in to pressure is best.', '{"question":"What should you do if a friend offers drugs?","wrong_answer":"Take them to fit in","correct_answer":"Refuse and tell a trusted adult"}'::jsonb, 'Fitting in feels more urgent than distant harm.', 'Offer "Take them to fit in" next to the right answer and ask the question again in a new situation.', 'Practise three refusal lines and walk away; name the friend who will stand with you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE.M_CR7_DA_PROVERBS_WINE', 'CRES.G7.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_ABUSE', 'Thinks Proverbs 20:1 praises wine, missing that it warns "wine is a mocker".', '{"question":"What does Proverbs 20:1 say about wine and beer?","wrong_answer":"They make a person wise","correct_answer":"Wine is a mocker and beer a brawler; whoever is led astray by them is not wise"}'::jsonb, 'The learner knows wine from the wedding at Cana and expects praise.', 'Offer "They make a person wise" beside "Wine is a mocker and beer a brawler; whoever is led astray by them is not wise" and ask the child to choose.', 'Read Proverbs 20:1 and 23:29-35 and list the harms they name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.GAMBLING.M_CR7_GM_TYPE', 'CRES.G7.CHRIST.GAMBLING.GAMBLING', 'Thinks a game played for money among friends is not gambling because it is not in a betting shop.', '{"question":"Which of these is gambling?","wrong_answer":"Playing cards for money with friends is just a game","correct_answer":"Playing cards for money is gambling"}'::jsonb, 'Some games of chance do not look like betting.', 'Offer "Playing cards for money with friends is just a game" beside "Playing cards for money is gambling" and ask the child to choose.', 'List types in Kenya: sports betting on phones, lotteries, casinos, card games for money, pool for money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.GAMBLING.M_CR7_GM_EFFECT', 'CRES.G7.CHRIST.GAMBLING.GAMBLING', 'Thinks gambling usually makes savings grow, because adverts show winners.', '{"question":"Which is an effect of gambling?","wrong_answer":"Savings grow","correct_answer":"Debt and family quarrels"}'::jsonb, 'Adverts show winners, not losers.', 'Offer "Savings grow" next to the right answer and ask the question again in a new situation.', 'Show the maths: most players lose. List effects on the gambler and family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.GAMBLING.M_CR7_GM_WEALTH', 'CRES.G7.CHRIST.GAMBLING.GAMBLING', 'Misquotes 1 Timothy 6:10.', '{"question":"What does 1 Timothy 6:10 warn about?","wrong_answer":"Working hard","correct_answer":"The love of money"}'::jsonb, 'The verse is quoted short and the learner fills in a guess.', 'Offer "Working hard" next to the right answer and ask the question again in a new situation.', 'Read 1 Timothy 6:10 in full and underline "the love of".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.MONEY_RICHES.M_CR7_MR_MONEY_EVIL', 'CRES.G7.CHRIST.GAMBLING.MONEY_RICHES', 'Thinks 1 Timothy 6:10 says money itself is evil, so a Christian should have none.', '{"question":"What does 1 Timothy 6:10 say is a root of all kinds of evil?","wrong_answer":"Money","correct_answer":"The love of money"}'::jsonb, 'The verse is often quoted short as "money is the root of all evil".', 'Offer "Money" beside "The love of money" and ask the child to choose.', 'Read the whole verse and underline "the love of". Money can be used well; loving it is the danger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.MONEY_RICHES.M_CR7_MR_QUICK_RICH', 'CRES.G7.CHRIST.GAMBLING.MONEY_RICHES', 'Thinks getting rich quickly by luck is a blessing, against Proverbs 13:11 and 28:20.', '{"question":"What does Proverbs 13:11 say about money gathered little by little?","wrong_answer":"It is too slow and wasted effort","correct_answer":"It grows, while dishonest or quick money dwindles"}'::jsonb, 'Stories of jackpot winners make quick money look like the best kind.', 'Offer "It is too slow and wasted effort" beside "It grows, while dishonest or quick money dwindles" and ask the child to choose.', 'Compare two savers on a chart: little by little each week against one big bet. Read Proverbs 28:20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.MONEY_RICHES.M_CR7_MR_TREASURE_BANK', 'CRES.G7.CHRIST.GAMBLING.MONEY_RICHES', 'Thinks "treasures in heaven" (Matthew 6:19-21) means money saved in a bank.', '{"question":"What are treasures in heaven, in Matthew 6:19-21?","wrong_answer":"Money kept safe in a bank","correct_answer":"Good deeds, generosity and a life given to God"}'::jsonb, 'The child hears "store up" and thinks of savings accounts.', 'Offer "Money kept safe in a bank" beside "Good deeds, generosity and a life given to God" and ask the child to choose.', 'Read 1 Timothy 6:18 beside Matthew 6:20: be rich in good deeds, generous and willing to share.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.MONEY_RICHES.M_CR7_MR_THIEF_KEEP', 'CRES.G7.CHRIST.GAMBLING.MONEY_RICHES', 'Thinks Ephesians 4:28 tells a former thief only to stop stealing, missing work and sharing.', '{"question":"According to Ephesians 4:28, what should a former thief do?","wrong_answer":"Only stop stealing","correct_answer":"Stop stealing, work honestly with his hands and share with those in need"}'::jsonb, 'The child stops at the first command of the verse.', 'Offer "Only stop stealing" beside "Stop stealing, work honestly with his hands and share with those in need" and ask the child to choose.', 'Read Ephesians 4:28 in three parts and write them as three steps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.GAMBLING.GAMBLING.M_CR7_GM_ONE_BET', 'CRES.G7.CHRIST.GAMBLING.GAMBLING', 'Thinks one small bet with pocket money cannot become a habit.', '{"question":"Kip places one small bet with his pocket money and wins. What is the danger?","wrong_answer":"None: one bet cannot harm","correct_answer":"A win can pull him into betting again and into debt"}'::jsonb, 'The first win feels like a reward, not a trap.', 'Offer "None: one bet cannot harm" beside "A win can pull him into betting again and into debt" and ask the child to choose.', 'Discuss how habits begin; read 1 Corinthians 6:12: "I will not be mastered by anything".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_CR7_SM_PLATFORM', 'CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Counts any phone app, such as a calculator, as a social media platform.', '{"question":"Which is a social media platform?","wrong_answer":"A calculator","correct_answer":"WhatsApp"}'::jsonb, 'Any app on a phone seems to be social media.', 'Offer "A calculator" next to the right answer and ask the question again in a new situation.', 'Say social media is for sharing and talking with others; sort apps: WhatsApp, TikTok, Facebook (social), calculator, torch (not).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_CR7_SM_BULLY', 'CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks the right answer to cyberbullying is to reply with insults.', '{"question":"What should you do about cyberbullying?","wrong_answer":"Reply with insults","correct_answer":"Save it and tell a trusted adult"}'::jsonb, 'Hitting back online feels like standing up for oneself.', 'Offer "Reply with insults" next to the right answer and ask the question again in a new situation.', 'Steps: do not reply, save the evidence, block, report, tell a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_CR7_SM_PRIVATE', 'CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks sharing other people''s pictures without asking is harmless.', '{"question":"You have a funny photo of a classmate. What is responsible?","wrong_answer":"Post it, it is only a joke","correct_answer":"Ask first and do not post what could hurt them"}'::jsonb, 'Sharing a friend''s photo seems kind or funny.', 'Offer "Post it, it is only a joke" beside "Ask first and do not post what could hurt them" and ask the child to choose.', 'Ask: did they agree? Could it hurt them? Keep others'' pictures and information private.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_CR7_SM_DELETED_GONE', 'CRES.G7.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks a post that is deleted is gone for ever, so anything may be posted.', '{"question":"You post something unkind and delete it after an hour. Is it gone?","wrong_answer":"Yes, deleting removes it for ever","correct_answer":"No: others may have saved or shared it"}'::jsonb, 'The delete button seems to undo everything.', 'Offer "Yes, deleting removes it for ever" beside "No: others may have saved or shared it" and ask the child to choose.', 'Show how screenshots and forwarding work; think before posting (Philippians 4:8).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
